// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/camera/Camera.tsx. Edit it there, then run `npm run sync:film`.
import React, { createContext, useContext } from "react";
import { AbsoluteFill, Easing, interpolate, random, useCurrentFrame } from "remotion";

/**
 * Declarative camera for the paper world.
 *
 *   const cam = useCamera([{ frame: 0, scale: 1 }, { frame: 120, scale: 1.12, x: 80, focus: 0.6 }]);
 *   <Camera state={cam}> <ParallaxLayer depth={0.2}>…</ParallaxLayer> … </Camera>
 *
 * depth: 0 = infinitely far (never moves), 1 = the focal stage plane, >1 = foreground (moves more).
 * focus: which depth is sharp; layers blur with distance from it.
 */
export type CameraState = {
  x: number;
  y: number;
  scale: number;
  rotate: number;
  focus: number;
  shake: number;
};

export type CameraKey = Partial<CameraState> & {
  frame: number;
  /** Easing used for the move that ARRIVES at this key. */
  ease?: (t: number) => number;
};

const DEFAULT: CameraState = { x: 0, y: 0, scale: 1, rotate: 0, focus: 1, shake: 0 };
const PROPS: (keyof CameraState)[] = ["x", "y", "scale", "rotate", "focus", "shake"];
const cinematic = Easing.bezier(0.45, 0, 0.2, 1);

export const cameraAt = (keys: CameraKey[], frame: number): CameraState => {
  const sorted = [...keys].sort((a, b) => a.frame - b.frame);
  const state = { ...DEFAULT };
  for (const prop of PROPS) {
    // Carry values forward so each key only needs to state what changes.
    const track: { frame: number; value: number; ease?: (t: number) => number }[] = [];
    let last = DEFAULT[prop];
    for (const k of sorted) {
      if (k[prop] !== undefined) last = k[prop] as number;
      track.push({ frame: k.frame, value: last, ease: k.ease });
    }
    if (track.length === 0) continue;
    if (frame <= track[0].frame) {
      state[prop] = track[0].value;
      continue;
    }
    if (frame >= track[track.length - 1].frame) {
      state[prop] = track[track.length - 1].value;
      continue;
    }
    for (let i = 1; i < track.length; i++) {
      const a = track[i - 1];
      const b = track[i];
      if (frame <= b.frame) {
        state[prop] = interpolate(frame, [a.frame, b.frame], [a.value, b.value], {
          easing: b.ease ?? cinematic,
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        break;
      }
    }
  }
  return state;
};

export const useCamera = (keys: CameraKey[]): CameraState => {
  const frame = useCurrentFrame();
  return cameraAt(keys, frame);
};

const CameraContext = createContext<CameraState>(DEFAULT);

export const Camera: React.FC<{ state: CameraState; children: React.ReactNode }> = ({
  state,
  children,
}) => <CameraContext.Provider value={state}>{children}</CameraContext.Provider>;

export const ParallaxLayer: React.FC<{
  depth: number;
  children: React.ReactNode;
  /** Max blur in px when this layer is far from the focal depth. */
  blurStrength?: number;
  style?: React.CSSProperties;
}> = ({ depth, children, blurStrength = 10, style }) => {
  const cam = useContext(CameraContext);
  const frame = useCurrentFrame();
  const shakeX = cam.shake ? (random(`sx-${frame}`) - 0.5) * cam.shake * depth : 0;
  const shakeY = cam.shake ? (random(`sy-${frame}`) - 0.5) * cam.shake * depth : 0;
  const scale = 1 + (cam.scale - 1) * depth;
  const blur = Math.min(blurStrength, Math.abs(depth - cam.focus) * blurStrength);
  return (
    <AbsoluteFill
      style={{
        transform: `translate(${-cam.x * depth + shakeX}px, ${-cam.y * depth + shakeY}px) scale(${scale}) rotate(${cam.rotate * depth}deg)`,
        transformOrigin: "50% 50%",
        filter: blur > 0.3 ? `blur(${blur.toFixed(2)}px)` : undefined,
        ...style,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};
